def find_max_subsequence_length(A, D):
    if not A:
        return 0

    max_length = 0
    current_length = 1

    for i in range(1, len(A)):
        if abs(A[i] - A[i - 1]) <= D:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1

    max_length = max(max_length, current_length)
    return max_length
